package Servlet;
import Controlador.*; import Modelo.Usuarios; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.time.*; import java.time.format.*;
@WebServlet("/DashboardEnfermeria") public class DashboardEnfermeriaServlet extends HttpServlet { protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{Object o=r.getSession(false)==null?null:r.getSession(false).getAttribute("usuario");if(!(o instanceof Usuarios)||((Usuarios)o).getRolDescripcion()==null||!((Usuarios)o).getRolDescripcion().toLowerCase().contains("enfermer")){s.sendRedirect(r.getContextPath()+"/Index.jsp");return;}Usuarios u=(Usuarios)o;DashboardEnfermeriaDAO d=new DashboardEnfermeriaDAO();r.setAttribute("nombreEnfermera",u.getNombres());r.setAttribute("fechaActual",LocalDate.now().format(DateTimeFormatter.ofPattern("EEEE d 'de' MMMM",new java.util.Locale("es","CO"))));r.setAttribute("totalPacientes",new PacienteDAO().contarPacientes());r.setAttribute("totalMedicamentos",new MedicamentoDAO().contarMedicamentos());r.setAttribute("pendientes",d.pendientes());r.setAttribute("stockBajo",d.stockBajo());r.setAttribute("activos",d.activos());r.setAttribute("finalizados",d.finalizados());r.setAttribute("proximaCita",d.proximaCita(u.getid_Usuarios()));r.setAttribute("actividad",d.actividad());r.getRequestDispatcher("/Vista/DashboardEnfermeria.jsp").forward(r,s);}}
